-- Potassium loading screen (Christmas Edition)
-- Visual replica only; no executor functionality.
local Players = game:GetService('Players')
local TweenService = game:GetService('TweenService')
local UserInputService = game:GetService('UserInputService')
local RunService = game:GetService('RunService')
local CoreGui = game:GetService('CoreGui')
local ContentProvider = game:GetService('ContentProvider')
local player = Players.LocalPlayer
local URL = 'https://raw.githubusercontent.com/brookbrookcms-cmyk/Cookie-Hub/main/ChristmasBackground.jpg'
local W,H,R = 916,601,9
local SPIN_DURATION, DOWNLOAD_DURATION, FILL_DURATION, HOLD, FADE = 1.65,3,1.45,2,0.35

for _,parent in ipairs({CoreGui,player:WaitForChild('PlayerGui')}) do
    local old=parent:FindFirstChild('PotassiumLoader')
  if old then old:Destroy() end
end
local gui=Instance.new('ScreenGui')
gui.Name='PotassiumLoader'; gui.IgnoreGuiInset=true; gui.ResetOnSpawn=false
gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling; gui.DisplayOrder=100
if not pcall(function() gui.Parent=CoreGui end) then gui.Parent=player.PlayerGui end
local function corner(obj)
   local c=Instance.new('UICorner'); c.CornerRadius=UDim.new(0,R); c.Parent=obj
end
local window=Instance.new('Frame')

window.Name='Window';window.Size=UDim2.fromOffset(W,H)
window.AnchorPoint=Vector2.new(.5,.5);window.Position=UDim2.fromScale(.5,.5)
window.BackgroundColor3=Color3.new(1,1,1)
window.BorderSizePixel=0;window.ClipsDescendants=true;window.Parent=gui;corner(window)
local border=Instance.new('UIStroke')
border.Color=Color3.fromRGB(80,65,100);border.Thickness=.7
border.Transparency=1;border.Parent=window
local splash=Instance.new('Frame')
splash.Name='WhiteStartup';splash.Size=UDim2.fromScale(1,1)
splash.BackgroundColor3=Color3.new(1,1,1);splash.BorderSizePixel=0
splash.ZIndex=30;splash.Parent=window;corner(splash)
local bg=Instance.new('ImageLabel')
bg.Name='Background';bg.Size=UDim2.fromScale(1,1);bg.BackgroundTransparency=1
bg.ScaleType=Enum.ScaleType.Crop;bg.ZIndex=1;bg.Parent=window;corner(bg)
local tint=Instance.new('Frame')
tint.Size=UDim2.fromScale(1,1);tint.BackgroundColor3=Color3.new(0,0,0)
tint.BackgroundTransparency=.88;tint.BorderSizePixel=0;tint.ZIndex=2;tint.Parent=window;corner(tint)
local bar=Instance.new('Frame')
bar.Size=UDim2.new(1,0,0,42);bar.BackgroundTransparency=1;bar.ZIndex=6;bar.Parent=window
local function button(name,txt,x)
   local b=Instance.new('TextButton');b.Name=name;b.Size=UDim2.fromOffset(46,40)
   b.Position=UDim2.new(1,x,0,1);b.BackgroundTransparency=1;b.BorderSizePixel=0
    b.Text=txt;b.Font=Enum.Font.Gotham;b.TextSize=17
   b.TextColor3=Color3.fromRGB(220,218,226);b.ZIndex=7;b.Parent=bar
  b.MouseEnter:Connect(function()
      TweenService:Create(b,TweenInfo.new(.15),{BackgroundTransparency=.3,BackgroundColor3=name=='Close' and Color3.fromRGB(205,45,55) or Color3.fromRGB(65,65,75)}):Play()
    end)
  b.MouseLeave:Connect(function()
    TweenService:Create(b,TweenInfo.new(.15),{BackgroundTransparency=1}):Play()
    end)
  return b
end
local min=button('Minimize','−',-138)
local max=button('Maximize','□',-92)
local close=button('Close','×',-46)
local content=Instance.new('Frame')
content.Name='LoadingContent';content.AnchorPoint=Vector2.new(.5,.5)
content.Position=UDim2.fromScale(.5,.455);content.Size=UDim2.fromOffset(450,100)
content.BackgroundTransparency=1;content.ZIndex=4;content.Parent=window
local ring=Instance.new('Frame')
ring.Name='ProgressRing';ring.AnchorPoint=Vector2.new(.5,.5)
ring.Position=UDim2.new(.5,0,0,28);ring.Size=UDim2.fromOffset(40,40)

ring.BackgroundTransparency=1;ring.ZIndex=5;ring.Parent=content
-- Antialiased circle frames generated at 4x resolution and embedded in this script.
local HttpService=game:GetService('HttpService')
local RING_DATA=[==[]==]
local ringImage=Instance.new('ImageLabel')
ringImage.Name='SmoothProgress';ringImage.BackgroundTransparency=1

ringImage.AnchorPoint=Vector2.new(.5,.5)
ringImage.Position=UDim2.fromScale(.5,.5)
ringImage.Size=UDim2.fromOffset(40,40)
ringImage.ImageRectSize=Vector2.new(80,80)
ringImage.ScaleType=Enum.ScaleType.Stretch
ringImage.ZIndex=7;ringImage.Parent=ring
local function ringFrame(index)
  index=math.clamp(index,0,59)
   ringImage.ImageRectOffset=Vector2.new((index%10)*80,math.floor(index/10)*80)
end

ringFrame(0)
local TRACK=Color3.fromRGB(92,92,96)
local WHITE=Color3.fromRGB(255,255,255)
local SCALE=6
local SEGMENTS=540
local RADIUS=17*SCALE
local fallbackRing=Instance.new('Frame')
fallbackRing.Name='FallbackRing';fallbackRing.BackgroundTransparency=1
fallbackRing.AnchorPoint=Vector2.new(.5,.5);fallbackRing.Position=UDim2.fromScale(.5,.5)
fallbackRing.Size=UDim2.fromOffset(40*SCALE,40*SCALE);fallbackRing.Parent=ring
local scale=Instance.new('UIScale')
scale.Scale=1/SCALE
scale.Parent=fallbackRing
local segments={}
for i=1,SEGMENTS do
    local angle=-math.pi/2+(i-.5)*math.pi*2/SEGMENTS
    local part=Instance.new('Frame')
   part.Name='RingSegment'..i
   part.AnchorPoint=Vector2.new(.5,.5)
   part.Position=UDim2.new(.5,math.cos(angle)*RADIUS,.5,math.sin(angle)*RADIUS)
    part.Size=UDim2.fromOffset(1.55*SCALE,3.05*SCALE)
    part.Rotation=math.deg(angle)+90
   part.BackgroundColor3=TRACK
    part.BorderSizePixel=0
  part.ZIndex=6
    part.Parent=fallbackRing
  local c=Instance.new('UICorner');c.CornerRadius=UDim.new(1,0);c.Parent=part
  segments[i]=part
end
local check=Instance.new('Frame')
check.Name='Checkmark';check.BackgroundTransparency=1
check.Size=UDim2.fromScale(1,1);check.Visible=false;check.ZIndex=8;check.Parent=fallbackRing
local function strokeBetween(x1,y1,x2,y2,thickness)
   x1,y1,x2,y2=x1*SCALE,y1*SCALE,x2*SCALE,y2*SCALE

    local dx,dy=x2-x1,y2-y1
   local line=Instance.new('Frame')
   line.AnchorPoint=Vector2.new(.5,.5)
  line.Position=UDim2.new(.5,(x1+x2)/2,.5,(y1+y2)/2)
  line.Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy)+2*SCALE,thickness*SCALE)
   line.Rotation=math.deg(math.atan2(dy,dx))
  line.BackgroundColor3=WHITE;line.BorderSizePixel=0;line.ZIndex=9;line.Parent=check
   local c=Instance.new('UICorner');c.CornerRadius=UDim.new(1,0);c.Parent=line
end
strokeBetween(-6.1,-.1,-1.7,4.1,3.35)
strokeBetween(-1.7,4.1,6.5,-4.9,3.35)
-- Two small arcs chase around the gray track during update checking.
local lastArcA,lastArcB=-1,-1
local lastFilled=-1
local ARC_LENGTH=56
local function paintArc(startIndex,color)
   for j=0,ARC_LENGTH-1 do
        local idx=((startIndex+j-1)%SEGMENTS)+1
      segments[idx].BackgroundColor3=color
  end
end

local function fallbackSpinners(t)
  local pos=math.floor(t*SEGMENTS*2.15)%SEGMENTS+1
   if pos==lastArcA then return end
   if lastArcA>0 then
      paintArc(lastArcA,TRACK)
        paintArc(lastArcB,TRACK)
   end
  local opposite=((pos-1+SEGMENTS/2)%SEGMENTS)+1
    paintArc(pos,WHITE)
  paintArc(opposite,WHITE)
  lastArcA,lastArcB=pos,opposite
end
local function fallbackClear()
    for _,part in ipairs(segments) do part.BackgroundColor3=TRACK end
    lastArcA,lastArcB=-1,-1
   lastFilled=0
end
local function fallbackFill(t)
    t=math.clamp(t,0,1)
   local filled=math.floor(t*SEGMENTS+.5)
  if filled>lastFilled then
    for i=math.max(1,lastFilled+1),filled do
            segments[i].BackgroundColor3=WHITE
      end
        lastFilled=filled
   end
    check.Visible=t>=1
end

local ringLoaded=false
local ringAssetReady=false
local function setSmoothRing()
  if ringAssetReady and not ringLoaded then
    ringLoaded=true
        ringImage.Visible=true
    fallbackRing.Visible=false
   end
end
local function prepareRing()
   if not (writefile and (getcustomasset or getsynasset)) then
        warn('[Potassium] Smooth ring requires a custom-asset loader; using UI fallback.')
        return false
  end
  local ok,err=pcall(function()
      local filename='potassium_smooth_ring_v35.png'
      writefile(filename,HttpService:Base64Decode(RING_DATA))
        local asset=(getcustomasset or getsynasset)(filename)
    assert(type(asset)=='string' and #asset>0,'Empty image asset')
    ringImage.Image=asset
    end)
  if not ok then
      warn('[Potassium] Ring asset failed: '..tostring(err))
    return false
   end
-- PreloadAsync. Don't permanently choose the blocky fallback on that basis.
   pcall(function() ContentProvider:PreloadAsync({ringImage}) end)
  ringAssetReady=true
    if ringImage.IsLoaded then setSmoothRing() end
  return true
end
local function updateSpinners(t)
   if ringLoaded then ringFrame(math.min(23,math.floor(t*24))) else fallbackSpinners(t) end
end
local function clearSpinners()
   if not ringLoaded then fallbackClear() end
end
local function updateRing(t)
  if ringLoaded then ringFrame(24+math.min(35,math.floor(math.clamp(t,0,1)*35))) else fallbackFill(t) end
end
local status=Instance.new('TextLabel')
status.Name='Status';status.AnchorPoint=Vector2.new(.5,.5)
status.Position=UDim2.new(.5,0,0,73);status.Size=UDim2.fromOffset(440,28)
status.BackgroundTransparency=1;status.Text='Checking For Updates'
status.Font=Enum.Font.GothamMedium;status.TextSize=14
status.TextStrokeColor3=Color3.fromRGB(248,248,250);status.TextStrokeTransparency=.65
status.TextColor3=Color3.fromRGB(248,248,250)
status.TextXAlignment=Enum.TextXAlignment.Center
status.ZIndex=5;status.Parent=content
local alive=true
local function shutdown()
   if not alive then return end
  alive=false;gui:Destroy()
end
close.MouseButton1Click:Connect(shutdown)
local minimized,maximized=false,false
local normalSize=window.Size
min.MouseButton1Click:Connect(function()
   minimized=not minimized
    TweenService:Create(window,TweenInfo.new(.2),{Size=minimized and UDim2.fromOffset(window.AbsoluteSize.X,42) or (maximized and UDim2.fromScale(.9,.9) or normalSize)}):Play()
end)
max.MouseButton1Click:Connect(function()
    maximized=not maximized;minimized=false
    TweenService:Create(window,TweenInfo.new(.2),{Size=maximized and UDim2.fromScale(.9,.9) or normalSize}):Play()
end)
local dragging,dragStart,startPos=false,nil,nil
bar.InputBegan:Connect(function(input)
   if input.UserInputType==Enum.UserInputType.MouseButton1 then
        dragging=true;dragStart=input.Position;startPos=window.Position
    end
end)
UserInputService.InputEnded:Connect(function(input)

  if input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false end
end)
UserInputService.InputChanged:Connect(function(input)
   if dragging and input.UserInputType==Enum.UserInputType.MouseMovement then
    local d=input.Position-dragStart
        window.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+d.X,startPos.Y.Scale,startPos.Y.Offset+d.Y)
    end
end)
local HttpService=game:GetService('HttpService')
local assetFn=getcustomasset or getsynasset
local function getAsset(filename)
  if not assetFn then return nil end
   local ok,asset=pcall(function() return assetFn(filename) end)
    return ok and asset or nil
end
local function loadBackground()

    if isfile and isfile('potassium_christmas_background_v1.jpg') then
        local cached=getAsset('potassium_christmas_background_v1.jpg')
      if cached then bg.Image=cached;return true end
  end
  if not (writefile and assetFn) then return false end
  local req=request or http_request or (syn and syn.request) or (http and http.request)
  local data
    if req then
    local ok,r=pcall(function() return req({Url=URL,Method='GET'}) end)

      if ok and r and r.Body and (r.StatusCode==200 or r.Success) then data=r.Body end
    end
   if not data then
    local ok,r=pcall(function() return game:HttpGet(URL) end)
    if ok then data=r end
  end
  if data and alive then
      local ok=pcall(function() writefile('potassium_christmas_background_v1.jpg',data) end)
      if ok then
            local asset=getAsset('potassium_christmas_background_v1.jpg')
         if asset and alive then bg.Image=asset;return true end
    end
   end
   return false
end
local imagesReady=false
local started=0
local finished=false
local function reveal()
  if finished or not alive then return end
   finished=true
   window.BackgroundColor3=Color3.fromRGB(16,12,24)
   border.Transparency=.65
  splash:Destroy()
   started=os.clock()
  imagesReady=true
end
task.delay(8,reveal)
task.spawn(function()
   prepareRing()
  if loadBackground() then
      pcall(function() ContentProvider:PreloadAsync({bg}) end)

    end
    if alive then reveal() end
end)
local cleared=false
local conn
conn=RunService.RenderStepped:Connect(function()
    if not alive then conn:Disconnect();return end
  if not imagesReady then return end
    if ringAssetReady and not ringLoaded and ringImage.IsLoaded then
      setSmoothRing()
   end

  local elapsed=os.clock()-started
   if elapsed<SPIN_DURATION then
      status.Text='Checking For Updates'
        updateSpinners(elapsed/SPIN_DURATION)
    return
    end
   local downloadElapsed=elapsed-SPIN_DURATION
   if downloadElapsed<DOWNLOAD_DURATION then
        status.Text='Downloading Files'
      updateSpinners(downloadElapsed/DOWNLOAD_DURATION)
    return
    end
   status.Text='Downloading Files'
   local fillElapsed=downloadElapsed-DOWNLOAD_DURATION
   if not cleared then clearSpinners();cleared=true end
  updateRing(fillElapsed/FILL_DURATION)
   if fillElapsed>=FILL_DURATION then
        conn:Disconnect()
      updateRing(1)
    status.Text='Ready'
    task.delay(HOLD,function()
            if not alive then return end
      local info=TweenInfo.new(FADE,Enum.EasingStyle.Quad)
         local function fade(obj,props)
            TweenService:Create(obj,info,props):Play()
      end

      fade(bg,{ImageTransparency=1})
            fade(tint,{BackgroundTransparency=1})
      fade(window,{BackgroundTransparency=1})
      fade(border,{Transparency=1})
      fade(status,{TextTransparency=1})
            fade(ringImage,{ImageTransparency=1})
      fade(fallbackRing,{BackgroundTransparency=1})
      for _,seg in ipairs(segments) do fade(seg,{BackgroundTransparency=1}) end
         for _,child in ipairs(check:GetChildren()) do if child:IsA('Frame') then fade(child,{BackgroundTransparency=1}) end end
         for _,b in ipairs({min,max,close}) do
        fade(b,{TextTransparency=1,BackgroundTransparency=1})
            end
      task.wait(FADE)
            shutdown()
    end)
  end
end)
